import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useDonors } from '../contexts/DonorContext';
import { useOffline } from '../contexts/OfflineContext';
import DonorCard from '../components/donors/DonorCard';
import MediaUploader from '../components/media/MediaUploader';
import apiService from '../services/apiService';

const AgentDashboard = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { loading } = useDonors();
    const { isOffline } = useOffline();

    const [agent, setAgent] = useState(null);
    const [donorsData, setDonorsData] = useState({ sheepDonors: [], cowDonors: [] });
    const [isLoading, setIsLoading] = useState(true);
    const [selectedDonor, setSelectedDonor] = useState(null);
    const [uploadedImages, setUploadedImages] = useState([]);
    const [uploadedVideo, setUploadedVideo] = useState(null);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submitSuccess, setSubmitSuccess] = useState(false);

    // Load agent data and their donors
    useEffect(() => {
        const loadAgentData = async () => {
            if (!id) {
                navigate('/');
                return;
            }

            setIsLoading(true);
            try {
                console.log(`Loading data for agent ${id}`);

                // Get agent info
                const agentInfo = await apiService.getAgent(id);
                if (!agentInfo) {
                    console.error(`Agent ${id} not found`);
                    navigate('/');
                    return;
                }

                setAgent(agentInfo);

                // Get agent's assigned donors
                const donationsData = await apiService.getAgentDonations(id);
                console.log(`Retrieved donations for agent ${id}:`, donationsData);

                // Process sheep donations
                const sheepDonors = (donationsData.sheepDonations || [])
                    .filter(d => d.status !== 'done')
                    .map(d => ({
                        id: d.donor_id,
                        firstName: d.first_name,
                        lastName: d.last_name,
                        whatsappNumber: d.whatsapp_number,
                        status: d.status,
                        type: 'sheep',
                        donationId: d.id,
                        price: d.price
                    }));

                // Process cow donations
                const cowDonors = [];
                Object.values(donationsData.cowGroups || {}).forEach(group => {
                    if (!Array.isArray(group)) return;

                    group
                        .filter(d => d.status !== 'done')
                        .forEach(d => {
                            cowDonors.push({
                                id: d.donor_id,
                                firstName: d.first_name,
                                lastName: d.last_name,
                                whatsappNumber: d.whatsapp_number,
                                status: d.status,
                                type: 'cow',
                                donationId: d.id,
                                price: d.price,
                                cowGroupId: d.cow_group_id
                            });
                        });
                });

                setDonorsData({ sheepDonors, cowDonors });
                console.log(`Processed ${sheepDonors.length} sheep donors and ${cowDonors.length} cow donors`);

            } catch (error) {
                console.error(`Error loading agent ${id} data:`, error);
            } finally {
                setIsLoading(false);
            }
        };

        loadAgentData();
    }, [id, navigate]);

    // Handle donor selection
    const handleDonorSelect = (donor) => {
        setSelectedDonor(donor);
        setUploadedImages([]);
        setUploadedVideo(null);
        setSubmitSuccess(false);
    };

    // Handle image upload
    const handleImageUpload = (files) => {
        const imageFiles = Array.from(files).map(file => ({
            file,
            preview: URL.createObjectURL(file)
        }));
        setUploadedImages(imageFiles);
    };

    // Handle video upload
    const handleVideoUpload = (files) => {
        if (files.length > 0) {
            const videoFile = {
                file: files[0],
                preview: URL.createObjectURL(files[0])
            };
            setUploadedVideo(videoFile);
        }
    };

    // Handle mark as done
    const handleMarkDone = async () => {
        if (!selectedDonor) return;
        setIsSubmitting(true);

        try {
            const media = {
                images: uploadedImages.map(img => img.file),
                video: uploadedVideo?.file
            };

            // Upload media
            for (const image of media.images) {
                await apiService.uploadMedia(selectedDonor.donationId, 'image', image);
            }

            if (media.video) {
                await apiService.uploadMedia(selectedDonor.donationId, 'video', media.video);
            }

            // Update donation status
            await apiService.updateDonationStatus(selectedDonor.donationId, 'done');

            // Show success message
            setSubmitSuccess(true);

            // Refresh donors list
            const donationsData = await apiService.getAgentDonations(id);

            // Process sheep donations
            const sheepDonors = (donationsData.sheepDonations || [])
                .filter(d => d.status !== 'done')
                .map(d => ({
                    id: d.donor_id,
                    firstName: d.first_name,
                    lastName: d.last_name,
                    whatsappNumber: d.whatsapp_number,
                    status: d.status,
                    type: 'sheep',
                    donationId: d.id,
                    price: d.price
                }));

            // Process cow donations
            const cowDonors = [];
            Object.values(donationsData.cowGroups || {}).forEach(group => {
                if (!Array.isArray(group)) return;

                group
                    .filter(d => d.status !== 'done')
                    .forEach(d => {
                        cowDonors.push({
                            id: d.donor_id,
                            firstName: d.first_name,
                            lastName: d.last_name,
                            whatsappNumber: d.whatsapp_number,
                            status: d.status,
                            type: 'cow',
                            donationId: d.id,
                            price: d.price,
                            cowGroupId: d.cow_group_id
                        });
                    });
            });

            setDonorsData({ sheepDonors, cowDonors });

            // Clear form after success
            setTimeout(() => {
                setSelectedDonor(null);
                setUploadedImages([]);
                setUploadedVideo(null);
                setSubmitSuccess(false);
            }, 2000);
        } catch (error) {
            console.error('Error marking donor as done:', error);
            alert('Failed to mark as done. Please try again.');
        } finally {
            setIsSubmitting(false);
        }
    };

    const canMarkDone = uploadedImages.length > 0 && uploadedVideo !== null && !isSubmitting;

    // If loading, show loading spinner
    if (isLoading || loading) {
        return (
            <div className="flex justify-center items-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-green-500"></div>
            </div>
        );
    }

    // If no agent found, redirect to home
    if (!agent) {
        navigate('/');
        return null;
    }

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Donor List Column */}
            <div className="lg:col-span-1">
                <div className="bg-white rounded-lg shadow-sm p-6">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-lg font-medium">
                            {agent.agent_name}'s Workspace
                        </h2>
                        <button
                            onClick={async () => {
                                setIsLoading(true);
                                try {
                                    const donationsData = await apiService.getAgentDonations(id);

                                    // Process sheep donations
                                    const sheepDonors = (donationsData.sheepDonations || [])
                                        .filter(d => d.status !== 'done')
                                        .map(d => ({
                                            id: d.donor_id,
                                            firstName: d.first_name,
                                            lastName: d.last_name,
                                            whatsappNumber: d.whatsapp_number,
                                            status: d.status,
                                            type: 'sheep',
                                            donationId: d.id,
                                            price: d.price
                                        }));

                                    // Process cow donations
                                    const cowDonors = [];
                                    Object.values(donationsData.cowGroups || {}).forEach(group => {
                                        if (!Array.isArray(group)) return;

                                        group
                                            .filter(d => d.status !== 'done')
                                            .forEach(d => {
                                                cowDonors.push({
                                                    id: d.donor_id,
                                                    firstName: d.first_name,
                                                    lastName: d.last_name,
                                                    whatsappNumber: d.whatsapp_number,
                                                    status: d.status,
                                                    type: 'cow',
                                                    donationId: d.id,
                                                    price: d.price,
                                                    cowGroupId: d.cow_group_id
                                                });
                                            });
                                    });

                                    setDonorsData({ sheepDonors, cowDonors });
                                } catch (error) {
                                    console.error('Error refreshing data:', error);
                                } finally {
                                    setIsLoading(false);
                                }
                            }}
                            className="text-blue-600 hover:text-blue-800"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                <path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 010 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" />
                            </svg>
                        </button>
                    </div>

                    {donorsData.sheepDonors.length === 0 && donorsData.cowDonors.length === 0 ? (
                        <div className="text-center py-8">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-green-500 mx-auto mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                            </svg>
                            <h3 className="text-xl font-medium text-green-600">All Tasks Complete!</h3>
                            <p className="text-gray-500 mt-2">All donations have been processed.</p>
                            <button
                                onClick={() => navigate('/')}
                                className="mt-4 bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-md"
                            >
                                Return to Dashboard
                            </button>
                        </div>
                    ) : (
                        <>
                            {/* Sheep Donors */}
                            <div className="mb-6">
                                <h3 className="font-medium text-gray-700 mb-2">Sheep Donors</h3>
                                {donorsData.sheepDonors.length > 0 ? (
                                    <div className="space-y-2 max-h-96 overflow-y-auto pr-2">
                                        {donorsData.sheepDonors.map(donor => (
                                            <DonorCard
                                                key={donor.donationId}
                                                donor={donor}
                                                onClick={() => handleDonorSelect(donor)}
                                                isSelected={selectedDonor?.donationId === donor.donationId}
                                            />
                                        ))}
                                    </div>
                                ) : (
                                    <p className="text-gray-500 text-sm">No sheep donors assigned</p>
                                )}
                            </div>

                            {/* Cow Groups */}
                            <div>
                                <h3 className="font-medium text-gray-700 mb-2">Cow Groups</h3>
                                {donorsData.cowDonors.length > 0 ? (
                                    (() => {
                                        const groups = {};
                                        donorsData.cowDonors.forEach(donor => {
                                            const groupId = donor.cowGroupId;
                                            if (!groups[groupId]) groups[groupId] = [];
                                            groups[groupId].push(donor);
                                        });

                                        return Object.entries(groups).map(([groupId, donors]) => (
                                            <div key={groupId} className="border border-gray-200 rounded-lg p-3 mb-3">
                                                <h4 className="font-medium text-sm mb-2">Cow Group {groupId}</h4>
                                                <div className="space-y-2">
                                                    {donors.map(donor => (
                                                        <DonorCard
                                                            key={donor.donationId}
                                                            donor={donor}
                                                            onClick={() => handleDonorSelect(donor)}
                                                            isSelected={selectedDonor?.donationId === donor.donationId}
                                                        />
                                                    ))}
                                                </div>
                                            </div>
                                        ));
                                    })()
                                ) : (
                                    <p className="text-gray-500 text-sm">No cow groups assigned</p>
                                )}
                            </div>
                        </>
                    )}
                </div>
            </div>

            {/* Media Upload Column */}
            <div className="lg:col-span-2">
                {selectedDonor ? (
                    <div className="bg-white rounded-lg shadow-sm p-6">
                        <div className="flex justify-between items-start mb-6">
                            <div>
                                <h2 className="text-xl font-medium">{selectedDonor.firstName} {selectedDonor.lastName}</h2>
                                <p className="text-gray-500">{selectedDonor.type === 'sheep' ? 'Sheep' : 'Cow (1/7 share)'}</p>
                                <p className="text-gray-500">Status: <span className={`font-medium ${selectedDonor.status === 'done' ? 'text-green-600' :
                                        selectedDonor.status === 'sending' ? 'text-yellow-600' : 'text-blue-600'
                                    }`}>{selectedDonor.status}</span></p>
                            </div>
                        </div>

                        {selectedDonor.status === 'done' ? (
                            <div className="text-center py-8">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-green-500 mx-auto mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                                </svg>
                                <h3 className="text-xl font-medium text-green-600">Sacrifice Completed</h3>
                                <p className="text-gray-500 mt-2">This sacrifice has been recorded and the media has been uploaded.</p>
                            </div>
                        ) : submitSuccess ? (
                            <div className="text-center py-8">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-green-500 mx-auto mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                                </svg>
                                <h3 className="text-xl font-medium text-green-600">Successfully Submitted!</h3>
                                <p className="text-gray-500 mt-2">The sacrifice has been marked as complete.</p>
                            </div>
                        ) : (
                            <>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                                    <div>
                                        <h3 className="font-medium text-gray-700 mb-2">Upload Images</h3>
                                        <MediaUploader
                                            type="image"
                                            multiple={true}
                                            onUpload={handleImageUpload}
                                            uploadedFiles={uploadedImages}
                                            setUploadedFiles={setUploadedImages}
                                            disabled={isSubmitting}
                                        />
                                    </div>

                                    <div>
                                        <h3 className="font-medium text-gray-700 mb-2">Upload Video</h3>
                                        <MediaUploader
                                            type="video"
                                            multiple={false}
                                            onUpload={handleVideoUpload}
                                            uploadedFiles={uploadedVideo ? [uploadedVideo] : []}
                                            setUploadedFiles={(files) => setUploadedVideo(files[0] || null)}
                                            disabled={isSubmitting}
                                        />
                                    </div>
                                </div>

                                <div className="border-t pt-4">
                                    <button
                                        onClick={handleMarkDone}
                                        disabled={!canMarkDone}
                                        className={`w-full py-2 px-4 rounded-md ${isSubmitting ? 'bg-gray-400 cursor-not-allowed' : canMarkDone ? 'bg-green-600 hover:bg-green-700 text-white' : 'bg-gray-300 cursor-not-allowed text-gray-500'}`}
                                    >
                                        {isSubmitting ? (
                                            <>
                                                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white inline-block" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                                </svg>
                                                Processing...
                                            </>
                                        ) : isOffline ? 'Mark as Done (Will Sync Later)' : 'Mark as Done & Send Confirmation'}
                                    </button>
                                    {!canMarkDone && !isSubmitting && (
                                        <p className="text-sm text-center mt-2 text-gray-500">
                                            Please upload both images and video to continue
                                        </p>
                                    )}
                                </div>
                            </>
                        )}
                    </div>
                ) : (
                    <div className="bg-white rounded-lg shadow-sm p-6 flex flex-col items-center justify-center h-full min-h-[400px]">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-gray-300 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                        <h3 className="text-xl font-medium text-gray-500 mb-2">No Donor Selected</h3>
                        <p className="text-gray-400 text-center">
                            Select a donor from the list to upload images and video of their sacrifice.
                        </p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default AgentDashboard;
